report DeviceModels "Device Model Loan Analysis"
  by dimension
  date purchase_date
  entity device_model_loan_analysis
  role view_reports
  currency KES
  cache 60
  maxrange 1200

  group model_name
  rows "Device Model"
  sort loans desc

  loans = count loans "Loans Issued"
  issued = sum loans.principal "Amount Issued" money
  paid = sum loans.total_paid "Total Paid" money
  balance = sum loans.balance "Outstanding Balance" money

  headline {label}: {loans} loans issued, {issued} issued, {paid} paid and {balance} outstanding.

  remark loans == 0 | neutral | No loans | No loans were issued for {label}.
  remark balance > 0 | watch | Outstanding Balance | {label} has {balance} outstanding.
  remark true | neutral | Loan Performance | {label}: {loans} loans, {paid} paid and {balance} outstanding.
